using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly PaymentGateway _gateway;

    public PaymentGatewayTests()
    {
        _gateway = new PaymentGateway();
    }

    #region ChargeAsync Tests

    [TestMethod]
    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccessResult()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 49.99m);

        Assert.IsNotNull(result);
        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_ValidCharge_ReturnsNonEmptyChargeId()
    {
        var result = await _gateway.ChargeAsync("tok_valid_visa", 100.00m);

        Assert.IsTrue(result.Success);
        Assert.AreNotEqual(string.Empty, result.ChargeId);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    [DataRow(-100.50)]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentException(double amount)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public async Task ChargeAsync_NullOrEmptyToken_ThrowsArgumentException(string? cardToken)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.ChargeAsync(cardToken!, 10.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_MinimumAmount_Succeeds()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 0.01m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    [DataRow(1.00)]
    [DataRow(99.99)]
    [DataRow(1000.00)]
    public async Task ChargeAsync_VariousValidAmounts_AllSucceed(double amount)
    {
        var result = await _gateway.ChargeAsync("tok_valid", (decimal)amount);

        Assert.IsTrue(result.Success);
        Assert.IsNotNull(result.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_TwoCharges_ReturnDistinctChargeIds()
    {
        var result1 = await _gateway.ChargeAsync("tok_valid", 10.00m);
        var result2 = await _gateway.ChargeAsync("tok_valid", 20.00m);

        Assert.AreNotEqual(result1.ChargeId, result2.ChargeId);
    }

    [TestMethod]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailureResult()
    {
        var result = await _gateway.ChargeAsync("tok_declined", 50.00m);

        Assert.IsFalse(result.Success);
    }

    #endregion

    #region RefundAsync Tests

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessResult()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 75.00m);

        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsNotNull(refund);
        Assert.IsTrue(refund.Success);
        Assert.IsNotNull(refund.RefundId);
    }

    [TestMethod]
    public async Task RefundAsync_ValidRefund_ReturnsNonEmptyRefundId()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 25.00m);

        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.AreNotEqual(string.Empty, refund.RefundId);
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    public async Task RefundAsync_NullOrEmptyChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExactlyAsync<ArgumentException>(
            async () => await _gateway.RefundAsync(chargeId!));
    }

    [TestMethod]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailure()
    {
        var result = await _gateway.RefundAsync("chg_nonexistent_12345");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    public async Task RefundAsync_SameChargeTwice_SecondRefundFails()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 50.00m);

        var firstRefund = await _gateway.RefundAsync(charge.ChargeId);
        var secondRefund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(firstRefund.Success);
        Assert.IsFalse(secondRefund.Success);
    }

    [TestMethod]
    public async Task RefundAsync_TwoRefunds_ReturnDistinctRefundIds()
    {
        var charge1 = await _gateway.ChargeAsync("tok_valid", 10.00m);
        var charge2 = await _gateway.ChargeAsync("tok_valid", 20.00m);

        var refund1 = await _gateway.RefundAsync(charge1.ChargeId);
        var refund2 = await _gateway.RefundAsync(charge2.ChargeId);

        Assert.AreNotEqual(refund1.RefundId, refund2.RefundId);
    }

    #endregion
}

